import{j as e}from"./react-Br30PpYv.js";import{P as p,H as c,a as i,E as r}from"./PublicLayout-DIjCmXot.js";import"./LegalFooter-B4YzYzM1.js";import"./index-CVrx4uvx.js";import"./LogoMark-CMb8n6uJ.js";const o=[{version:"0.20.3",title:"catalog links",blocks:[{type:"heading",text:"Catalog"},{type:"list",items:[{inline:[{type:"bold",text:"Catalog links of StatTrak and Souvenir items find the item."},{type:"text",text:" The link searched the catalog for the full name, prefix included, but the catalog lists skins without it."}],news:!1}]}]},{version:"0.20.2",title:"market page fixes",blocks:[{type:"heading",text:"Market"},{type:"list",items:[{inline:[{type:"bold",text:"Items on the market page link to their catalog entry."}],news:!1},{inline:[{type:"bold",text:"The column headers say which price is shown:"},{type:"text",text:" the lowest listing on each marketplace; buy orders are not used."}],news:!1},{inline:[{type:"bold",text:"Large gaps and long marketplace names no longer break across lines."}],news:!1},{inline:[{type:"bold",text:"The marketplace comparison was removed."},{type:"text",text:" It was hard to read and answered nothing the other two views don't."}],news:!1}]}]},{version:"0.20.1",title:"market page right after an update",blocks:[{type:"heading",text:"Market"},{type:"list",items:[{inline:[{type:"bold",text:"The market page fills right after an update."},{type:"text",text:' Market changes were only computed in the price run every four hours, so after the update the page said "No market readings yet" until the next run; they are now computed from the stored daily prices as soon as they are missing.'}],news:!1}]}]},{version:"0.20.0",title:"market movers",blocks:[{type:"heading",text:"Market"},{type:"list",items:[{inline:[{type:"bold",text:"A Market page shows what moved: the biggest risers and fallers of the catalogue, gaps between marketplaces and how the marketplaces compare."},{type:"text",text:' Changes compare the first price reading of each UTC day ("as of 02:08 UTC") over 1, 7 and 30 days. Items under $1 or with fewer than 10 offers are left out by default, because they swing by hundreds of percent on a single listing. Gaps show the listing price difference large and what is left after your marketplace fees below it; selling for Steam balance is off unless you switch it on. The gaps list can be sorted by profit or by profit percent, and both lists start with the top 10 and show more on request.'}],news:!0}]},{type:"heading",text:"Fees"},{type:"list",items:[{inline:[{type:"bold",text:"C5Game has its own selling fee in the fee table (5 %, editable)."},{type:"text",text:" A holding valued from C5Game was netted with your default fee, because C5Game had no entry; saved fee tables get it added once."}],news:!1}]}]},{version:"0.19.3",title:"changelog page",blocks:[{type:"heading",text:"Changelog"},{type:"list",items:[{inline:[{type:"bold",text:"The changelog has its own page."},{type:"text",text:" Every release of the last 30, newest first, at forcebuy.net/changelog and under About in the settings."}],news:!1}]}]},{version:"0.19.2",title:"month-first dates",blocks:[{type:"heading",text:"Steam"},{type:"list",items:[{inline:[{type:"bold",text:'Steam market purchases and sales on accounts that show dates as "Aug 18" now get their dates.'},{type:"text",text:' Steam writes English dates month-first for some countries (US), and the market and inventory history readers only understood "18 Aug", so these receipts were stored undated and could not be placed in time or matched to items. Missing dates are filled in on the next market history read; reconnect your Steam session if it has expired.'}],news:!1}]}]},{version:"0.19.1",title:"trade cost card",blocks:[{type:"heading",text:"Costs"},{type:"list",items:[{inline:[{type:"bold",text:'The cost card of a traded item no longer says "nothing was given" when you gave items.'},{type:"text",text:" After the update the costs were only worked out at each account's daily read, and until then the card read a missing calculation as an empty trade; they are now worked out right after an update, and the card lists what you gave and says when its cost is unknown."}],news:!1},{inline:[{type:"bold",text:"Items from other games given in a trade make the cost unknown instead of being left out."},{type:"text",text:" Gems, trading cards and other non-CS items have no record in ForceBuy; they were skipped, so such a trade showed no cost source or a sum that was too low."}],news:!1},{inline:[{type:"bold",text:'The cost card of a traded item sits in the right column, above "Listed for sale",'},{type:"text",text:" instead of across the whole page."}],news:!1}]}]},{version:"0.19.0",title:"costs through trades",blocks:[{type:"heading",text:"Costs"},{type:"list",items:[{inline:[{type:"bold",text:"Items you got in a trade carry the cost of what you gave for them."},{type:"text",text:" The cost of the items you traded away (and of what they came from) goes to what came back. Several items received are split by their prices on the trade day; without a price for that day their cost stays unknown. The item page shows how the cost was worked out, item by item. Can be turned off in Settings."}],news:!0},{inline:[{type:"bold",text:"Money paid or received in a trade can be added."},{type:"text",text:' On the item page, for a trade like "item plus money for a knife". If you got more money than your items cost, the difference counts as realised profit on the day of the trade.'}],news:!1},{inline:[{type:"bold",text:"Items moved between your own accounts keep their cost."}],news:!1},{inline:[{type:"bold",text:'"Traded for" lists only the items of that trade.'},{type:"text",text:" It showed everything traded in the same minute, also with other people, because trades were grouped by the minute rather than by partner."}],news:!1},{inline:[{type:"bold",text:"A price you typed counts as the cost of an item you traded up or away."},{type:"text",text:" Trade-ups ignored a hand-entered price on items whose record came from the Steam history."}],news:!1}]},{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"Figure tiles show their day change again."},{type:"text",text:" Since gross and net, the net line under a figure took a row of its own and pushed the day change and the small chart out of the bottom of the tile; it now sits beside them."}],news:!1}]}]},{version:"0.18.0",title:"gross and net",blocks:[{type:"heading",text:"Gross and net"},{type:"list",items:[{inline:[{type:"bold",text:"Every figure with a marketplace fee shows both: what the buyer pays and what you keep."},{type:"text",text:` The buyer's price stays the big number, what is left after the fee sits on a small line under it - in the header, Holdings, the item page, Collections, History and the dashboard tiles. A Steam sale's buyer's price is worked out from what Steam reports and marked "≈". Hover a figure to see the fee. The sale price field says it wants the price as the marketplace reported it.`}],news:!0},{inline:[{type:"bold",text:"A stack of sold items shows its total sale price."},{type:"text",text:" The figure under a stack's sale price was the total after fees standing under the price of one item."}],news:!1}]},{type:"heading",text:"Realised profit"},{type:"list",items:[{inline:[{type:"bold",text:"Realised profit counts every sale you made, not only the items shown as past holdings."},{type:"text",text:' A sale and its purchase are both tied to the item they belong to, also when the item left long ago and has no row in Holdings. Those sales now count in the header and on the dashboard, with the same fees and cost rules as everything else. Before, realised profit was 0 unless "past items" was turned on. Sales whose cost is not known (traded in, no purchase on record) are not counted as profit; the header says how many.'}],news:!0},{inline:[{type:"bold",text:"Purchases and Sales have their own pages."},{type:"text",text:' The two sides of History, each with its own filters and saved views. Sales show the cost and the profit of every sale, before and after the fee; a cost taken from a cost rule is marked "rule", and a sale without a known cost says so instead of showing 0. History has the same two columns.'}],news:!0}]},{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"Dashboards by marketplace and origin."},{type:"text",text:' A new workspace template, "Marketplaces & origin", shows value by where items came from, realised profit by where they were sold, and purchases, sales and fees per marketplace. Charts can group holdings by "Origin" and "Sold on" and transactions by "Marketplace", and sum the marketplace fee.'}],news:!0},{inline:[{type:"bold",text:"A trade between two of your own connected Steam accounts is a move, not a sale."},{type:"text",text:' It shows as "Moved to own account", has "Own account" as its origin on the other side and does not count as realised profit. The cost does not move with it yet.'}],news:!1},{inline:[{type:"bold",text:'"Net cash flow" was too high by the CSFloat and Buff163 fees.'},{type:"text",text:` Steam reports a sale after its fee, CSFloat and Buff163 report what the buyer paid, and the dashboard added both up as they came. Sales are now taken after the fee everywhere; "Amount" is the buyer's price and "Amount after fees" what you kept.`}],news:!1},{inline:[{type:"bold",text:'"After fees" values use the fee of the market the price comes from.'},{type:"text",text:" They used one fee for everything, the one picked under Marketplace fees, so an item priced on CSFloat lost Steam's fee and Steam's cash-out rate. The chosen fee now only applies to prices you set by hand and to markets without a fee on record."}],news:!1},{inline:[{type:"bold",text:'New measure "Realised P/L before fees"'},{type:"text",text:" next to the realised P/L."}],news:!1}]},{type:"heading",text:"Export"},{type:"list",items:[{inline:[{type:"bold",text:"The CSV export has columns for gross and net."},{type:"text",text:" Sale price before and after the fee, value and unrealised P/L after the fee, realised P/L before the fee, and which fee was used. They come after the existing columns, so a file you import keeps working."}],news:!1}]},{type:"heading",text:"Storage units"},{type:"list",items:[{inline:[{type:"bold",text:"Items sold on CSFloat or Buff163 out of a storage unit no longer count as stored."},{type:"text",text:" A sale there leaves through a Steam trade that names no item id, so ForceBuy marked some other copy of the same name as traded and kept the sold one in the unit: on one account 38 cases sold in January still counted as held, at their full value. The copy the marketplace says it sold around that time is now the one that goes."}],news:!1}]},{type:"heading",text:"Stickers"},{type:"list",items:[{inline:[{type:"bold",text:"Stickers on sold items all show their price."},{type:"text",text:" On a sold or traded skin, a sticker only had a price when one of your held skins carried the same sticker, so for example two of the four stickers on a sold M4A1-S showed none. The price lookup only collected stickers from items you still hold."}],news:!1},{inline:[{type:"bold",text:"Sticker names with a comma stay one sticker."},{type:"text",text:' A name like "karrigan (Glitter, Champion) | Antwerp 2022" was read as two stickers, and every sticker image after it moved one slot along. Stored lists are mended once on their own.'}],news:!1}]},{type:"heading",text:"Fees"},{type:"list",items:[{inline:[{type:"bold",text:"Steam fees are exact to the cent."},{type:"text",text:" The buyer's price worked out from a Steam sale was 1 to 2 cents too high, and what you keep from a Steam price 1 to 2 cents too low, for three amounts in four. ForceBuy rounded Steam's 15 % as one fee; Steam takes its 5 % and the game's 10 % separately, each rounded down and at least one cent."}],news:!1}]}]},{version:"0.17.4",title:"past items from sign-up",blocks:[{type:"heading",text:"Settings"},{type:"list",items:[{inline:[{type:"bold",text:'"Past items" turned on during sign-up now takes effect right away.'},{type:"text",text:" The sign-up saved the choice but never started the run that builds those rows; only the same switch in the settings did. So the past only showed up after a later history read with a valid Steam session, and for some accounts not at all."}],news:!1}]}]},{version:"0.17.3",title:"realised profit groundwork",blocks:[{type:"heading",text:"Purchases and sales"},{type:"list",items:[{inline:[{type:"bold",text:"Purchases and sales read before your inventory history are now matched as soon as the history is in."},{type:"text",text:" The market history and the inventory history are read side by side, and on a new account the market read often finished first, before there was any item to match a receipt to. Nothing matched them afterwards except the next market read, which needs a Steam session, so receipts could stay unmatched for good and their prices were missing from your items."}],news:!1}]}]},{version:"0.17.2",title:"sync all in steps",blocks:[{type:"heading",text:"Syncing"},{type:"list",items:[{inline:[{type:"bold",text:'"Sync all" no longer holds up everyone else.'},{type:"text",text:" A full re-read of the inventory history now runs in steps of 20 pages and queues the rest behind other work, the way a first import does. Before, it read up to 2,000 pages in one go, and nobody's sync or import moved for that time."}],news:!1},{inline:[{type:"bold",text:'A "Sync all" that Steam paused now carries on after the pause.'},{type:"text",text:" The follow-up was meant to start ten minutes later, but the queue took it for the run that was still going and dropped it, so the re-read stopped where Steam paused it."}],news:!1}]}]},{version:"0.17.1",title:"improvements in handling steam sessions",blocks:[{type:"heading",text:"Syncing"},{type:"list",items:[{inline:[{type:"bold",text:"A new account's holdings are there at once; its history follows in the background."},{type:"text",text:" Connecting a Steam session reads the inventory right away and queues the inventory and market history as an import that runs in small steps. A banner shows your place in the queue, an estimate of when it starts, and how far back it has read. Before, each new account's whole history was read in one go, so everyone who connected later waited for their holdings too."}],news:!1},{inline:[{type:"bold",text:"Daily syncs and the Sync buttons of existing accounts no longer wait behind someone else's first import."},{type:"text",text:" They used to queue behind every full first read, for hours when several people connected at once."}],news:!1},{inline:[{type:"bold",text:"A queued first import survives a restart of the server."},{type:"text",text:" The queue lived only in memory, so an update lost it, and an import only came back with the next daily read."}],news:!1},{inline:[{type:"bold",text:'"Waiting · #n" in the job list is gone.'},{type:"text",text:" The number counted only your own jobs, so it said #1 while others were ahead."}],news:!1},{inline:[{type:"bold",text:"A history read that Steam paused now says how far it got."},{type:"text",text:" It reported 0 pages read even when it had read dozens, because the pages were only counted when the read finished without a pause."}],news:!1}]},{type:"heading",text:"Access"},{type:"list",items:[{inline:[{type:"bold",text:"See how long your Steam session lasts."},{type:"text",text:" A pasted Steam session ends after about 24 hours. The access panel now says until when it is valid, a banner warns two hours before it ends, and the field checks what you paste before it is sent: whose session it is, until when, or that it has already expired."}],news:!1},{inline:[{type:"bold",text:"One more read before a Steam session ends."},{type:"text",text:" In the last 45 minutes of a pasted session ForceBuy reads your inventory history and market history once more, so a session pasted in the morning is not wasted because the daily read comes after it has ended."}],news:!1},{inline:[{type:"bold",text:"Step-by-step help for copying a session, per browser."},{type:"text",text:" Chrome, Edge and Firefox, for Steam and Buff163. The old note that Chrome is not supported was wrong for pasting and is gone."}],news:!1},{inline:[{type:"bold",text:"One notice per login, confirmed once."},{type:"text",text:" Steam, Buff163 and CSFloat each get one box that says what is stored, how it is kept, what it is used for, how long it lasts and how to remove it, with a single checkbox. The warnings used to be spread over several places. Storing a CSFloat key now asks for that confirmation too."}],news:!1},{inline:[{type:"bold",text:"An optional browser extension is coming"},{type:"text",text:" that keeps sessions fresh, so they do not have to be pasted again; the login fields mention it."}],news:!1},{inline:[{type:"bold",text:"The access log shows when a use of your Steam login failed."},{type:"text",text:" Every use was written down as successful before ForceBuy even asked Steam, so an expired session never showed up as a failure there."}],news:!1}]}]},{version:"0.17.0",title:"containers on the dashboard",blocks:[{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"Unopened containers at a glance."},{type:"text",text:' Three new widgets under Allocation: the cases and capsules you still hold by value today, how many there are, and what they cost you. Charts can also be split and filtered by "Item type" (skin, sticker, container, ...), taken from the item catalogue, since Steam leaves the category of most cases empty.'}],news:!0},{inline:[{type:"bold",text:'"X of N entries" under a tile counts what the figure is about.'},{type:"text",text:" The share under a cost basis or profit counted every ledger row, sold and ignored ones included, so a cost basis known for every held item still read as partial. Cost and unrealised profit now count the items held, realised profit the items sold."}],news:!1}]},{type:"heading",text:"Syncing"},{type:"list",items:[{inline:[{type:"bold",text:"Sync buttons say when they can be used again."},{type:"text",text:' On forcebuy.net a sync can only be repeated after a while; the buttons stayed clickable and only the click said "not yet". They are now greyed out until then, with the time in their tooltip, on Inventories, History, the access panel, the trade sources and in the command palette.'}],news:!1}]},{type:"heading",text:"Pictures"},{type:"list",items:[{inline:[{type:"bold",text:"Small pictures replace their stand-in within a minute."},{type:"text",text:" While the small version of a picture was still being fetched, the full one was shown in its place and the browser kept that for an hour."}],news:!1}]},{type:"heading",text:"Data"},{type:"list",items:[{inline:[{type:"bold",text:"Back up the local app's database with one click"},{type:"text",text:' (local app only). Settings, Data, "Back up now" writes a copy of the whole database into the data folder and keeps the last ten. "Clear holdings" makes one first and refuses to delete anything if it cannot.'}],news:!1}]}]},{version:"0.16.1",title:"small bugfixes and performance improvements",blocks:[{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:'A stack opened in a "Listed" view counts only the listed copies.'},{type:"text",text:' The row said two, the stack panel listed all five copies of that item, because the panel ignored the "Listed" filter.'}],news:!1},{inline:[{type:"bold",text:'"Rows" no longer says "Stack identical" while one stack is open.'},{type:"text",text:" The list of an opened stack is always one row per copy; the field now says so and is locked until the Stack chip is removed."}],news:!1},{inline:[{type:"bold",text:"Filing one copy of a stack into a collection says what happens to the row:"},{type:"text",text:" the copy leaves the stack and gets a row of its own, since copies only stack with copies filed the same way."}],news:!1}]},{type:"heading",text:"Pictures"},{type:"list",items:[{inline:[{type:"bold",text:"Pictures of newly synced items arrive sooner."},{type:"text",text:" After a sync, ForceBuy fetched pictures for the first 400 items of all accounts in no particular order, so a new account's items mostly showed grey boxes until each picture was asked for. It now fetches the pictures of the account just synced, newest items first, behind any picture someone is waiting for, and the next sync no longer waits for it."}],news:!1}]},{type:"heading",text:"Data"},{type:"list",items:[{inline:[{type:"bold",text:'"Export SQLite" no longer fails while a sync is running.'},{type:"text",text:' It read the database page by page while the sync kept writing, then found a different number of rows than it had copied ("catalog_items: 1200 rows in the database, 400 in the export"). The export now reads one consistent state.'}],news:!1},{inline:[{type:"bold",text:"A second ForceBuy on the same data folder is turned away."},{type:"text",text:' Started with another port, it opened the same database as the running one, and two processes writing into one database can break it. It now stops with "ForceBuy is already running on this data folder".'}],news:!1}]},{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"The dashboard opens faster."},{type:"text",text:" The value-over-time chart and the trend lines of the stat tiles computed the same portfolio series twice at once, and the two then waited on each other to store it. They now share one computation."}],news:!1},{inline:[{type:"bold",text:"The first page after a pause no longer starts cold."},{type:"text",text:" Current prices were kept in memory for ten minutes, while new prices arrive every few hours; they are now kept until the next price run and read in again right after it."}],news:!1},{inline:[{type:"bold",text:"The refresh menu of a portfolio widget offers only what it keeps."},{type:"text",text:" Portfolio charts refresh at most every 30 minutes, since the series only moves with the price runs; the menu still offered 30s, 1m, 5m and 15m and then quietly ran at 30 minutes. It now offers Off, 30m and 1h, and marks the cadence actually in effect."}],news:!1}]}]},{version:"0.16.0",title:"how much to stack",blocks:[{type:"heading",text:"Settings"},{type:"list",items:[{inline:[{type:"bold",text:"Choose what Holdings stacks into one row."},{type:"text",text:' Settings, Valuation, "Stack identical items": off, same name, wear and origin, same name and wear (the default, as before), or same name and wear whatever the float, pattern, stickers and charms. With the last one the stack panel lists each copy with its float and stickers.'}],news:!0}]},{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"Historic items no longer stack with items you hold."},{type:"text",text:" A copy rebuilt from your history could share a row with an identical one still in your inventory, because the row did not tell the two apart; they are now always separate rows, as sold items already were."}],news:!1}]}]},{version:"0.15.0",title:"opening a stack",blocks:[{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"A stacked row opens as a stack."},{type:"text",text:' Clicking a row that stands for several identical items shows the whole stack beside the list: how many copies, their total value and profit (and for how many the cost is known), the range of costs, where they came from and the copies one by one, each of which opens on its own with a way back. "All N copies" lists them individually. Before, the panel and the item page showed only one copy of the stack, without saying so.'}],news:!0},{inline:[{type:"bold",text:"Set the cost of a whole stack at once."},{type:"text",text:' "Set cost for all N" in the stack panel, and "Set cost" for any selection, replace the cost of every copy in one step, with undo.'}],news:!0},{inline:[{type:"bold",text:"Mixed origins say so."},{type:"text",text:' A stack whose copies came from different places shows "Mixed" in the origin column, with the split in its tooltip, instead of the origin of one copy.'}],news:!1},{inline:[{type:"bold",text:"Right-click on a stack asks whether you mean one copy or all."},{type:"text",text:' "Mark sold" and "Add to collection" used to act on one copy of the stack, while ticking the row selected all of them.'}],news:!1},{inline:[{type:"bold",text:"The item page says when the item is one of several identical copies"},{type:"text",text:", and that changes there apply to that copy only. The quantity of an item read from Steam can no longer be edited there; changing it multiplied one copy and silently grew the stack."}],news:!1}]}]},{version:"0.14.21",title:"stacks that add up",blocks:[{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"The profit of a stacked row adds up its copies."},{type:"text",text:" A row that stands for several identical items took one copy's details for all of them: copies without a known cost counted as free, and every sold copy was charged the fee of the marketplace the first one went through. Each copy is now valued as it would be on its own row, and the stack shows their sum, as the portfolio total already did."}],news:!1}]}]},{version:"0.14.12",title:"settings tidy-up",blocks:[{type:"heading",text:"Settings"},{type:"list",items:[{inline:[{type:"bold",text:'The "Show Steam 13% fee" switch is gone.'},{type:"text",text:" It belonged to the old analytics page and has done nothing since that page was removed; no value anywhere changes."}],news:!1}]}]},{version:"0.14.11",title:"value beside the list",blocks:[{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"The panel beside the list shows the value line too."},{type:"text",text:" It drew its own copy of the price chart, which the value line had not reached; both now use the same chart."}],news:!1}]}]},{version:"0.14.10",title:"value on the item chart",blocks:[{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"The price history of an item shows what your copy is worth."},{type:"text",text:` Next to ask and bid, a "value" line follows the copy's value per piece over time: the price plus its sticker premium at that day's sticker prices, with its Doppler phase and your own prices, for the source picked above the chart.`}],news:!0}]}]},{version:"0.14.8",title:"no more blank pages",blocks:[{type:"heading",text:"Fixes"},{type:"list",items:[{inline:[{type:"bold",text:"A page no longer stays blank after an update."},{type:"text",text:` A tab left open across an update asked for the old version's page files, the server answered with the start page instead of "not found", and the page that should have loaded came up empty until you reloaded. The tab now reloads itself once in that case, and a page that still cannot load says so, with a reload button, while the navigation stays in place.`}],news:!1}]}]},{version:"0.14.6",title:"faster inventory reads",blocks:[{type:"heading",text:"Syncing"},{type:"list",items:[{inline:[{type:"bold",text:"An inventory read takes seconds instead of five to ten minutes."},{type:"text",text:" Each read also asked a float service for every item without a float, two calls per item, and that service has been refusing automated requests for weeks; the refusal was swallowed, so every item was tried again. Floats come from Steam's own answer, so the extra step is gone from the read."}],news:!1},{inline:[{type:"bold",text:"A sync you start yourself goes first."},{type:"text",text:" The daily reads of all accounts ran at the same minute and in one line, so a click after that waited behind all of them. Daily reads are now spread over the day, and syncs started by hand are taken before scheduled ones."}],news:!1}]},{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:'"Value over time" opens faster the second time.'},{type:"text",text:" The finished part of the line is now kept per account and only the newest days are calculated again. A change to your items, stickers, own prices or valuation settings, or a price added for an earlier day, recalculates the line from there."}],news:!1}]}]},{version:"0.14.5",title:"holdings that keep up",blocks:[{type:"heading",text:"Syncing"},{type:"list",items:[{inline:[{type:"bold",text:"Syncs started by hand have a short pause between them on forcebuy.net."},{type:"text",text:" An inventory can be read again after 30 minutes, the inventory history and market history after 6 hours, and a full read once a day. Clicking earlier shows when the next sync is possible. Signing in starts only the reads that are due, not all four again. A new inventory, a new cookie or a new marketplace key are read at once as before."}],news:!1}]},{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"Items on a trade or market hold show up in Holdings right away."},{type:"text",text:' The default "Sellable only" filter left out everything Steam marks as not marketable, including a fresh purchase that is only locked for a few days; it now counts items with a known lock end as sellable.'}],news:!1},{inline:[{type:"bold",text:"An expired Steam session no longer makes items disappear."},{type:"text",text:" With an expired cookie Steam answers the inventory with the public view, which leaves out Storage Units and items in the trade hold, and ForceBuy booked those as gone. It now checks the session first, and an incomplete read only adds and updates items."}],news:!1},{inline:[{type:"bold",text:"The row of the item open beside the list is highlighted across the whole row again."},{type:"text",text:" The frozen name and value columns kept their own background on top of the row's tint, so the highlight stopped short of the name."}],news:!1},{inline:[{type:"bold",text:"Holdings and the navigation load faster."},{type:"text",text:" The navigation asked for every collection with its full valuation on every page, although it only shows names and counts; it now asks for just those. The holdings list counts its stacks in the same query that reads them."}],news:!1}]},{type:"heading",text:"Marketplaces"},{type:"list",items:[{inline:[{type:"bold",text:"A CSFloat purchase that arrives before its item is matched later."},{type:"text",text:" A trade read while the item was not yet in the inventory was set aside, and the next read started after it, so it was never looked at again. Trades are now read with ten days of overlap."}],news:!1}]}]},{version:"0.14.4",title:"lighter pictures",blocks:[{type:"heading",text:"Performance"},{type:"list",items:[{inline:[{type:"bold",text:'Other pages no longer stall while "Value over time" is calculated.'},{type:"text",text:" The line for a large ledger took a second or more in one piece, and every other request on the server waited for it; it now pauses every few milliseconds to let them through."}],news:!1},{inline:[{type:"bold",text:"Item pictures are smaller."},{type:"text",text:" Some of Steam's pictures carry embedded text of several megabytes (a sticker capsule 5.5 MB for a 31 KB image); ForceBuy now drops it before storing and serving them."}],news:!1},{inline:[{type:"bold",text:'"Value over time" in daily values reads a fifth of the prices.'},{type:"text",text:" Every price run is still kept, but for a day only its last reading counts in daily, weekly and monthly views, and that one is now stored on its own."}],news:!1}]}]},{version:"0.14.3",title:"widgets that share their work",blocks:[{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"The dashboard, the header figures and collections load much faster on forcebuy.net."},{type:"text",text:" Widgets that ask for the same numbers at the same moment now wait for one calculation, and the latest prices are read once and kept for every request. Cause: on the server both were tied to each request's own database connection, so six widgets did the same work six times and every page read all prices again."}],news:!1},{inline:[{type:"bold",text:'"Value over time" and the value tile pick the same marketplace for an item without a price from your chosen source.'},{type:"text",text:" When several marketplaces reported at the same moment, the line took whichever it had read first, so its last point could differ from the tile. Now the order of the price sources decides, the same for both."}],news:!1},{inline:[{type:"bold",text:'"Value over time" loads only the range you pick on the chart.'},{type:"text",text:" It opens on the whole history in daily values; 7 days shows every price run. Before, every range was cut from the full hourly history, which took longest on the largest ledgers. With daily values each candle holds one reading per day, so intervals below a day are not offered there."}],news:!1},{inline:[{type:"bold",text:"Portfolio widgets refresh every 30 minutes at most."},{type:"text",text:" Prices are read every four hours, so a refresh every five minutes recalculated the same numbers. A longer cadence you chose stays."}],news:!1}]}]},{version:"0.14.2",title:"dashboard speed",blocks:[{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:'"Value over time" loads again on large ledgers.'},{type:"text",text:' It showed "This widget could not load" when the price history of all held items came to more than about 124,000 readings: since 0.14.0 they were read in one go and appended in a way that overflows the stack at that size.'}],news:!1}]}]},{version:"0.14.1",title:"steady navigation",blocks:[{type:"heading",text:"Navigation"},{type:"list",items:[{inline:[{type:"bold",text:"The icons no longer jump when the navigation unfolds."},{type:"text",text:" The groups had a small heading each (Portfolio, Market, Tools, Account) that the folded bar did not show, so every icon moved down when it opened over the page. The groups are now set apart by the same thin rule in both shapes, and the rows have the same height. Folding a single group away goes with the headings."}],news:!1}]}]},{version:"0.14.0",title:"the interface update",blocks:[{type:"paragraph",inline:[{type:"text",text:`A reworked interface: one icon set, switches, clearer states, charts on TradingView's chart library, and a "Value over time" that ends where your portfolio value stands. `},{type:"bold",text:"Your saved dashboards are reset to the new default workspace once with this update"},{type:"text",text:"; see Dashboard below."}]},{type:"heading",text:"What's new"},{type:"list",items:[{inline:[{type:"bold",text:"ForceBuy tells you what is new after an update."},{type:"text",text:` The first time you open a new version, a short window lists its new features (and those of any version you skipped), with "Don't show again" and a link to all news on X. Settings, About can switch it back on, and "Show recent news" next to "Show the tour again" opens the latest ones at any time. A new account gets the tour instead, and the demo neither.`}],news:!1}]},{type:"heading",text:"Look"},{type:"list",items:[{inline:[{type:"bold",text:"Columns can be resized and moved on the table itself."},{type:"text",text:" Drag the right edge of a column head to make it narrower or wider (double-click it to let the column size itself again), and drag a head onto another to move the column there. Works in Holdings, Collections, History, Prices, Inventories and the catalog list. The order is the same as in the column menu and is kept in saved views; widths are remembered per table in this browser."}],news:!0},{inline:[{type:"bold",text:"Empty places say what they are about."},{type:"text",text:' Empty lists carry an icon for their subject, and a search in Holdings that finds nothing offers the way back: "Show all", and "Search the catalog instead" when a name was typed.'}],news:!1},{inline:[{type:"bold",text:"Toasts wait while you read them."},{type:"text",text:" Resting the pointer on a toast holds it, and one that offers Undo shows a thin bar for the time left."}],news:!1},{inline:[{type:"bold",text:"Copy buttons on values you paste elsewhere"},{type:"text",text:': the Steam id (account and inventories) and the item name on the item page. The button appears on hover, says "Copied", and stays visible on touch screens.'}],news:!1},{inline:[{type:"bold",text:"The figures in the top bar show when they change"},{type:"text",text:': a short green or red glow in the direction they moved, and "Updated 3m ago" on hover over the value. They refreshed every five minutes without a sign. Off for anyone who set the system to reduce motion.'}],news:!1},{inline:[{type:"bold",text:"Number fields carry their unit and lose the spinners."},{type:"text",text:` The browser's two little arrows sat in every number field, and the unit stood as loose text beside it or only in the label. Percentages and minutes now show "%" or "min" inside the field, figures are right-aligned in the table font, and the Up and Down keys still step.`}],news:!1},{inline:[{type:"bold",text:"Date fields speak the app's language."},{type:"text",text:` They were the browser's own: the placeholder and month names in the browser's language ("tt.mm.jjjj" in a German browser) and a look of their own. They now show the date in the order of the region chosen under Numbers and dates, take it typed that way or as 2026-10-04, and have a small calendar with Today and Clear. A date that cannot be read is outlined instead of being dropped.`}],news:!1},{inline:[{type:"bold",text:"Deleting asks in the app's own dialog."},{type:"text",text:` Deleting a holding, a collection or an inventory, and removing all stored keys, used the browser's confirmation box: system colours, the whole tab blocked, and "OK" as the button that deletes. The dialog now names what goes (Delete "Sell next"?), the button says what it does, and Escape cancels.`}],news:!1},{inline:[{type:"bold",text:"Real icons in the navigation and the top bar."},{type:"text",text:" They were text symbols (▦ ⇄ ◐ ...) that looked different on every system and could hardly be told apart with the navigation folded; History and Currency used near-identical arrows. They are now one icon set (Lucide), drawn with the same thin line, as are the sort arrows in table heads and the arrows of the filter menus. The remaining symbols followed: closing and removing (x), moving a column, saving or starring a view, swapping currencies and opening a row in Admin."}],news:!1},{inline:[{type:"bold",text:"Buttons and fields have the text size they were meant to have."},{type:"text",text:" A base style outranked every size class on buttons, fields and lists, so all of them were drawn at the page's 13 pixels and stood out against the tables and menus at 12. They now share one size, and the filter bar reads as one row."}],news:!1},{inline:[{type:"bold",text:"Tooltips appear sooner and in the app's style."},{type:"text",text:" The explanations on icons, shortened names and states were the browser's own tooltips: about a second late, in system colours, and never for the keyboard. They now show after a short pause, at once when moving on to the next one, on keyboard focus too, and stay on screen near an edge."}],news:!1},{inline:[{type:"bold",text:"Drop-down lists look like the rest of the app."},{type:"text",text:" They were the operating system's own lists, in its font and colours, with a different arrow and height from the filter menus beside them. They now open as the app's own list with a tick at the current choice, a list is at least as wide as its field and wider where an entry needs it, and arrow keys, typing a letter and Escape work as before."}],news:!1},{inline:[{type:"bold",text:"Settings use switches for on/off choices."},{type:"text",text:" Sticker Percentage, filling gaps from Steam, pricing stickers, the free-arrival rules and the Steam fee were browser checkboxes in blue; they are switches in the app's colours, with a tick once on, placed in front of their label, and the description kept to a readable width. The SP percentage appears once SP is switched on. Saving is unchanged: the Save button at the top."}],news:!1},{inline:[{type:"bold",text:"States read as states."},{type:"text",text:` "Stored", "Not connected", "5d left", "Can trade", "Older than four days" and the like were framed capitals, the same as an item's wear and rarity; a row could carry four of them next to its numbers. They are now a coloured dot and a short phrase, and side notes such as "primary" or "optional" plain grey text. Badges remain for what an item is: wear, rarity, StatTrak, location.`}],news:!1},{inline:[{type:"bold",text:"Loading looks like loading."},{type:"text",text:` Item pictures, which come through the image proxy and can take seconds, showed as empty grey boxes; their frame now pulses until the picture fades in. An item's page shows its outline while it loads instead of "Loading..." in the corner, and the app starts on the logo instead of a blank page.`}],news:!1},{inline:[{type:"bold",text:"Menus, dialogs, tooltips, the search palette and notices ease in"},{type:"text",text:' instead of appearing in a single frame, for about a tenth of a second. Figures never move. With "reduce motion" set in the operating system, nothing animates.'}],news:!1},{inline:[{type:"bold",text:"Rarity is shown in its tier colour in Holdings too"},{type:"text",text:", as it already was in the catalog. The grid, the rarity column and the sticker picker showed it in grey, because only the catalog used the colour table. The colour is now mixed with the text colour, so pale tiers such as Base Grade stay readable on the light theme."}],news:!1},{inline:[{type:"bold",text:"Small grey text is easier to read."},{type:"text",text:" The muted grey used for column heads, hints and shortcuts measured 3.9:1 against the dark panels, below the 4.5:1 that small text needs; it is now 5.5:1, and darker on the light theme."}],news:!1},{inline:[{type:"bold",text:"The keyboard focus ring is visible everywhere."},{type:"text",text:" It was one pixel wide and sat directly on the border, so around a gold button it disappeared."}],news:!1},{inline:[{type:"bold",text:"Checkboxes use the gold accent"},{type:"text",text:" instead of the browser's blue."}],news:!1},{inline:[{type:"bold",text:"Wear badges are readable on the light theme."},{type:"text",text:" They used fixed marketplace colours made for a dark background; Factory New's pale cyan measured 1.4:1 on white. They now use the wear colours that are tuned for each theme."}],news:!1},{inline:[{type:"bold",text:"The theme follows your system by default."},{type:"text",text:' The appearance menu has a third choice, "System", which is now where a new visitor starts: dark when the operating system is dark, light otherwise, and it switches along. A dark or light theme you chose before stays as it was. The page no longer flashes white before a dark theme applies.'}],news:!1},{inline:[{type:"bold",text:"Dates are written in English, in your region's order."},{type:"text",text:' "Numbers and dates" set to German wrote "07. Okt. 2026" and an axis reading "Okt" between English labels; it now writes "7 Oct 2026" with the 24-hour clock and German number format. Exchange rates on the Currency page and in the trade maths follow the number format too; they were always written with a decimal point.'}],news:!1}]},{type:"heading",text:"Dashboard"},{type:"list",items:[{inline:[{type:"bold",text:"Unrealised P/L over time agrees with its tile"},{type:"text",text:`, and the tile now shows its trend as an amount ("+$1,124.51 1d"). The daily series counted every copy's value against only the costs that were known, so a drop or a gift without a price read as pure gain, and the line could fall while the tile rose.`}],news:!1},{inline:[{type:"bold",text:"New workspaces from a template."},{type:"text",text:" The + beside the workspace tabs offers Empty, Investor, Trader and Sticker collector, each with the widgets it starts with listed under its name."}],news:!0},{inline:[{type:"bold",text:"A ring chart with one huge slice turns into bars."},{type:"text",text:` When one part is three quarters or more of the whole (cases in "Value by category", say), the ring said nothing but that part's name. It now shows a bar per part with its share, and "Leave out Container" compares the rest at their own scale.`}],news:!1},{inline:[{type:"bold",text:'One "Edit" above the dashboard.'},{type:"text",text:' "Add widget", "Build chart" and "Arrange" stood over every dashboard at the same weight, on a phone too, though a dashboard is looked at far more often than changed. "Edit" opens the edit mode, which offers adding a widget, building a chart and moving panels, with Cancel and Done.'}],news:!1},{inline:[{type:"bold",text:"Portfolio value and Cost basis show where they are going"},{type:"text",text:": the change since yesterday as a small pill (the change over seven days on hover) and the last 30 days as a line under the figure. A figure alone did not say whether it was up or down. Unrealised P/L has no line yet: its daily series counts every position, the tile only those with a cost, and the two would disagree."}],news:!1},{inline:[{type:"bold",text:"Saved dashboards are reset once."},{type:"text",text:' Widgets saved before this update were the old charts; every workspace is replaced by the new default the next time the dashboard opens. Workspaces made afterwards are kept as usual. If you had built your own, "Add widget" and "Build chart" make them again.'}],news:!1},{inline:[{type:"bold",text:'"Value over time" now ends where "Portfolio value" stands.'},{type:"text",text:" The line read only the price snapshots of the regular price run, so items priced from the daily market lists had no value in it: on the demo it showed about 1,100 $ of a 98,000 $ portfolio, mostly missing the cases. It also left out Doppler phases, prices you set by hand and the Sticker Percentage (SP). It now values each point the way the tile does, daily prices and SP included when SP is on or set on an item, and a sold item counts until the day it was sold. This replaces the note in 0.13.0 that the history line stays without the stickers' share."}],news:!1},{inline:[{type:"bold",text:"Line and area charts over time use the TradingView chart"},{type:"text",text:" that the market chart already used: a real time axis, range and interval to pick in place, zoom, and a crosshair that reads every line. They were drawn with five fixed date labels and could not be zoomed. A widget keeps its look, an area stays an area. Bar, donut and table widgets are unchanged."}],news:!1},{inline:[{type:"bold",text:"Workspaces are tabs."},{type:"text",text:" The row of workspace names were small framed buttons; they are now tabs, underlined in gold for the one open, and the arrow keys move between them."}],news:!1},{inline:[{type:"bold",text:"The cost basis line starts hidden"},{type:"text",text:" on market charts, so it no longer sets the scale and squeezes the value into a flat strip. A click on it in the legend shows it, and again hides it; the zoom stays where it was."}],news:!1},{inline:[{type:"bold",text:"A line chart reads one value per point."},{type:"text",text:" The legend repeated the same number four times as open, high, low and close; that row now appears only for candles."}],news:!1},{inline:[{type:"bold",text:"Count bars under a price chart are quieter"},{type:"text",text:": a fifth of the height in a paler colour instead of a third in full colour, without an unlabelled axis. The count under the cursor is in the legend."}],news:!1}]},{type:"heading",text:"Catalog"},{type:"list",items:[{inline:[{type:"bold",text:"Float ranges on the wear scale."},{type:"text",text:' The float filter in the catalog and in Holdings has two handles on the bar from Factory New to Battle-Scarred, with the two numbers beside it for an exact value. "Below 0.07" is a drag to the end of the green.'}],news:!1},{inline:[{type:"bold",text:"A denser catalog."},{type:"text",text:` Five to six cards per row on a wide screen, each with the picture across the card on its rarity's colour. The catalog opens on the newest items, and sorting by name ignores leading quotes, which put "'Blueberries' Buckshot" ahead of every A.`}],news:!1}]},{type:"heading",text:"Calculator"},{type:"list",items:[{inline:[{type:"bold",text:"The calculator answers before you type."},{type:"text",text:" Trade maths starts at 100 so the page shows a result at once, and a bar splits the price into what you can spend, the cashout cost and the marketplace fee. The rate table lists the common currencies; the other two dozen are one click away."}],news:!1}]},{type:"heading",text:"Holdings"},{type:"list",items:[{inline:[{type:"bold",text:"What a sale would leave, per marketplace."},{type:"text",text:` The price table on an item page has a column "If sold": selling one at that marketplace's ask, after the fees you set under Settings, Valuation. Where the balance is not money (Steam Wallet) it shows what is left after your cashout rate, with the balance underneath; the best one is green. Marketplaces without a fee entry show nothing rather than a guess.`}],news:!0},{inline:[{type:"bold",text:"From the side panel to the item page in one movement."},{type:"text",text:` "Open full page" moves the item's picture from the panel into the page's header (Chrome, Edge and Safari; elsewhere, and with reduced motion, the page simply switches as before).`}],news:!1},{inline:[{type:"bold",text:"The spread between marketplaces as a picture."},{type:"text",text:" Above the price table on an item page, each marketplace's ask (dot) and bid (ring) sit on one scale, with the cheapest ask and the highest bid in green."}],news:!1},{inline:[{type:"bold",text:"Pictures in the table stand on their rarity's colour"},{type:"text",text:" like the cards and the item page, and follow the row density: a compact table gets smaller pictures instead of rows held apart by a fixed size."}],news:!1},{inline:[{type:"bold",text:"Right-click a row for its actions"},{type:"text",text:": open it, open it in the side panel, mark it sold, add it to a collection, copy its name or view it on the Steam market, without selecting it first. Shift and right-click still opens the browser's own menu."}],news:!0},{inline:[{type:"bold",text:"Tidier cells."},{type:"text",text:' A trade lock shows only the countdown ("6d left"); the day it ends is on hover. P/L sits on a light green or red ground, so the direction shows from across the table.'}],news:!1},{inline:[{type:"bold",text:"A save confirms itself where it happened."},{type:"text",text:' After saving in the edit panel, the changed part of the item page (figures, prices, stickers, timeline) shows a green frame and "Saved" for a moment, and Settings says "Settings saved" in the bar that asked to save. Before, a toast in the corner said "Saved." without saying what.'}],news:!1},{inline:[{type:"bold",text:"The timeline names its events."},{type:"text",text:' It showed internal ids such as "edited", "history_traded" or "market_sell"; these now read as "Edited", "Traded away (history)" or "Market sale matched".'}],news:!1},{inline:[{type:"bold",text:"Column presets."},{type:"text",text:' The column menu offers Standard, Compact, Trader and Collector above the free choice: one click sets a whole column layout for a quick glance, for trading (float, trade lock, ask, bid, listings) or for collecting (pattern, stickers, sticker value, rarity, collections). The column "Sold via" was labelled with a raw placeholder, because its text expected a value the column head never passes.'}],news:!1},{inline:[{type:"bold",text:"Value and P/L stay at the right edge of the Holdings table"},{type:"text",text:" while it scrolls sideways, as the name does on the left. With sixteen columns the table scrolls at 1440 pixels, and the two figures a row is read for were behind the scroll. They now always stand last."}],news:!1},{inline:[{type:"bold",text:"A finished inventory sync says what it brought"},{type:"text",text:': "Inventory synced: 12 new, 3 gone", with "Show" leading to Holdings, newest first. It ended without a word, and new items had to be found in the list.'}],news:!1},{inline:[{type:"bold",text:"An item's page leads back to the list it came from"},{type:"text",text:`, with its search, filters and order, and names it at the top (Holdings · "knife" or the collection). Beside it the item's place in that list ("3 of 5") with buttons, and J and K, for the next and previous item. The way back was a grey "Holdings" that opened the unfiltered list.`}],news:!1},{inline:[{type:"bold",text:"Holdings says how much its filters hide."},{type:"text",text:' The top bar counted every position while Holdings, which starts on sellable items in the main inventory, showed a fraction of them without saying why; "Reset filters" stayed greyed out because those two are defaults. The count now reads "105 items of 4,131 held" with a "Show all" link that lifts every filter, the defaults included.'}],news:!1},{inline:[{type:"bold",text:"The Holdings filters fit in one row."},{type:"text",text:' Search, inventory, location, kind, wear and rarity stay in the bar; rows, sellable, status, collection, trade lock, origin, listed and the narrower filters open under "Filters", which shows how many of them are set. Every filter in effect is listed as a chip under the bar ("Rarity: Covert", "Float: 0.01 - 0.2") and removed with its ×. The twelve fields used to take two rows above the first line of data.'}],news:!1},{inline:[{type:"bold",text:"The grid shows items the way marketplaces do."},{type:"text",text:` Each card has the picture large on a stage in its rarity's colour, the name on up to two lines, the float as a wear scale, and one value with its profit or loss as a coloured tag. It used to give the price twice and "No lock · MAIN INVENTORY" on every card; the lock and the place now show only when the item is locked or not in the main inventory. The selection box appears on hover or once something is selected.`}],news:!1},{inline:[{type:"bold",text:"Actions on a selection float at the bottom of the list."},{type:"text",text:' "Add to collection", "Mark sold" and the rest sat in the bar above the table, so picking rows far down meant scrolling back up; they now appear at the bottom of the screen as soon as something is selected.'}],news:!1},{inline:[{type:"bold",text:"Float is shown on the wear scale."},{type:"text",text:" In the table and the grid a float reads as a bar from Factory New to Battle-Scarred with a mark where the copy sits, the digits beside it."}],news:!1},{inline:[{type:"bold",text:"The item name stays in view while the table scrolls sideways."},{type:"text",text:" With many columns the Holdings table scrolls horizontally, and the name and picture scrolled away with it, leaving rows of numbers without an item. The selection box and the first column now stay put."}],news:!1},{inline:[{type:"bold",text:"Rows no longer double in height for a location."},{type:"text",text:' "Main inventory" and other labels wrapped onto a second line in narrow columns; they keep to one.'}],news:!1},{inline:[{type:"bold",text:"Filters with several choices are easier to use."},{type:"text",text:' Rarity and wear are listed in their ladder order with their colour (Consumer Grade up to Covert, Factory New to Battle-Scarred) instead of alphabetically; a long list such as the game collections has a search field; "only" next to a choice picks it alone; and the button reads "Covert +2" instead of "Rarity: 3".'}],news:!1},{inline:[{type:"bold",text:"An item's page opens with the item."},{type:"text",text:` The picture is shown large on its rarity's stage, and the figures (ask, bid, float, P/L, value, origin, acquired) sit in one strip instead of seven separate cards spread over half the screen; value and P/L are set larger, the float is shown on the wear scale, and a P/L with nothing to report is left out rather than shown as "-".`}],news:!1},{inline:[{type:"bold",text:'"Delete holding" moved into a "⋯" menu'},{type:"text",text:` on an item's page. It stood as a red button of the same size next to "Add to collection".`}],news:!1},{inline:[{type:"bold",text:"One way to edit an item: one panel, one Save."},{type:"text",text:` The item's page had three ways to change it, always open: "Price set by hand" with its own Save, the eight-field "Edit" form at the bottom with another Save, and "Edit" on the stickers, plus Sticker Percentage with a third Save. Every "Edit" on the page now opens the same panel from the right, with blocks for details, notes, the price set by hand, stickers and charms, and Sticker Percentage. It opens at the block you clicked; the block you are working in is outlined, and so is its place on the page. Changed blocks say so, and one Save at the foot stores all of them. The page itself only shows values; your notes appear under Timeline.`}],news:!1},{inline:[{type:"bold",text:"A price set by hand is one line under the marketplace prices"},{type:"text",text:', with "Edit" next to it, or "Set a price by hand" when there is none. Emptying both fields, or "Remove price set by hand", removes it on Save.'}],news:!1},{inline:[{type:"bold",text:"A sync that disagrees with a value you set by hand is shown at the top"},{type:"text",text:" of the item's page, with a link to review it. It was only visible in the edit form at the bottom."}],news:!1},{inline:[{type:"bold",text:"A click on an item in Holdings opens it beside the list."},{type:"text",text:` A panel shows the picture, value, P/L, ask, bid, float, cost, the price over the last 90 days and the stickers; Up and Down (or J and K) move to the next item, and the item shown is marked in the list. "Open full page" goes to the item's page, and so does a click with Ctrl, Cmd or the middle mouse button. Collections work the same way. Every row used to open its own page, which lost the list's scroll position and filters on the way back.`}],news:!0},{inline:[{type:"bold",text:"Panels and dialogs cover the whole height of the window."},{type:"text",text:" The status bar at the bottom was drawn over the foot of a panel opened from a list."}],news:!1}]},{type:"heading",text:"First start"},{type:"list",items:[{inline:[{type:"bold",text:"The logo is drawn as a vector."},{type:"text",text:" It stays sharp at every size, takes the colours of the light and dark theme, and the browser tab icon follows the system theme. The passcode screen shows it too."}],news:!1},{inline:[{type:"bold",text:"The tour shows what is new."},{type:"text",text:' Nine stops instead of five: the search (Ctrl+K), workspaces from a template, the columns of Holdings and the collections join the pages it showed before. "Show the tour again" at the top of Settings brings it back.'}],news:!1},{inline:[{type:"bold",text:"forcebuy.net shows what ForceBuy does in half a minute."},{type:"text",text:" The picture on the front page is now a short animated film with real market values: the inventory valued, the purchase price read from the Steam history, what a sale leaves after fees and cashout, a Doppler priced by its phase, Katowice 2014 stickers counted at 2.5 %, a storage unit and items already sold. It plays muted in your theme, with a pause button; with reduced motion it waits for you to start it."}],news:!1},{inline:[{type:"bold",text:"The demo can show what makes ForceBuy different."},{type:"text",text:' It had no history, no sales and no matched receipts, so History read "No account access yet" and realised P/L stood at 0.00 everywhere. The demo now has an inventory history (purchases, drops, unboxings, trades, a trade-up, deliveries into storage units), skins that were bought and sold again with profits and losses, Steam Market and marketplace receipts tied to their items, Sticker Percentage on skins with stickers, three collections, three saved Holdings views, one price set by hand, three copies listed for sale (two on CSFloat, one on the Steam market) and a cost set by hand that a later sync disagrees with, so "Use that" can be tried. Locally, turning the demo off removes these again and nothing you made yourself.'}],news:!1},{inline:[{type:"bold",text:"forcebuy.net says what ForceBuy is before asking you to sign in."},{type:"text",text:" The front page was the name, one sentence and two buttons. It now shows the app itself, four points on what it does (real purchase prices without typing, all marketplaces in one view, every copy valued with its float, stickers and phase, storage units and items that already left the account), signing in and the demo side by side, each with its note under it, and the local app for Windows as a third way."}],news:!1},{inline:[{type:"bold",text:"The demo notice is one thin line at the very top."},{type:"text",text:" It was a box on every page, about 50 pixels high and four lines on a phone."}],news:!1},{inline:[{type:"bold",text:"The tour points at what it explains."},{type:"text",text:' Each stop opens its page, lights up one thing on it (the figures at the top, the filters, "Add Steam inventory", the settings pages) and dims the rest, with the text next to it. It was a dialog in the middle of the screen, in front of the filter bar it was talking about. On a phone, where an element can be folded away, the text stands in the middle as before.'}],news:!1}]},{type:"heading",text:"Inventories"},{type:"list",items:[{inline:[{type:"bold",text:"A card per account while you have only a few."},{type:"text",text:" Up to nine accounts show as cards with avatar, access, standing, item count, last sync and the actions; search, filters, columns and paging come back from ten on."}],news:!1},{inline:[{type:"bold",text:"The demo no longer tries to sync with Steam."},{type:"text",text:' Its account is made up, so the scheduled inventory sync failed every time and showed "Failed" in the status bar of an untouched demo.'}],news:!1}]},{type:"heading",text:"Navigation"},{type:"list",items:[{inline:[{type:"bold",text:"Your account in the top right corner."},{type:"text",text:" The round button there (your Steam avatar on the web) opens who is signed in, theme and number format, Settings, the tour, feedback and Sign out. Theme and number format were behind a lone icon, and signing out was at the bottom of the settings."}],news:!1},{inline:[{type:"bold",text:"The navigation is grouped"},{type:"text",text:": Portfolio, Market, Tools and Account, each under a small heading that folds its group away; the group of the page you are on always shows. Nine equal entries had to be read top to bottom every time. Entries can still be dragged into any order, now within their group."}],news:!1},{inline:[{type:"bold",text:"The folded navigation opens over the page when you rest the pointer on it"},{type:"text",text:', and closes when you move away, so a look at another page no longer means unfolding, clicking and folding again, with the page jumping to a new width each time. The pin at its foot keeps it open. The folded bar is a little wider (52 pixels) with a rule between groups, and "[" folds and unfolds it.'}],news:!1},{inline:[{type:"bold",text:"Saved Holdings views and your collections are listed under their entry"},{type:"text",text:' in the navigation, each one click away. A star next to one pins it to a "Pinned" block at the top.'}],news:!1},{inline:[{type:"bold",text:'On forcebuy.net, search and "g p" no longer offer the price table.'},{type:"text",text:" It left the navigation for the admin area earlier, but Ctrl+K and the shortcut still led to it."}],news:!1},{inline:[{type:"bold",text:'"Currency" is now "Calculator"'},{type:"text",text:", in the navigation and on the page. The page starts with the fee calculator for a trade; currency conversion is the part below it."}],news:!1}]},{type:"heading",text:"Settings"},{type:"list",items:[{inline:[{type:"bold",text:"Settings are split into pages"},{type:"text",text:': Account, Marketplaces, Valuation, Data and backup, About, and the Danger zone last, listed on the left (along the top on a phone). It was one page of fifteen panels and about 4,400 pixels, with the danger zone in the same scroll. Search (Ctrl+K) finds each page, also by what is on it: "fees", "export", "csfloat".'}],news:!1},{inline:[{type:"bold",text:"One way to save settings."},{type:"text",text:" There was a Save at the top and another under every section, each saving everything. Now a bar appears at the foot as soon as something differs from what is stored, with Save and Discard. Panels that act at once, such as marketplace logins or notifications, still do."}],news:!1},{inline:[{type:"bold",text:"Export comes first under Data and backup."}],news:!1},{inline:[{type:"bold",text:"Marketplaces are one list."},{type:"text",text:' "Marketplace logins" and "Marketplaces outside Steam" listed the same marketplaces twice, with two different states. Each now has one row: whether a login is stored, when its history was last read, and "Add key" or "Replace", which opens the field. Reading and matching follow below the list.'}],news:!1},{inline:[{type:"bold",text:'Clearing all holdings asks you to type "clear holdings".'},{type:"text",text:" It was the browser's own confirmation dialog, one Enter away from deleting every holding."}],news:!1}]},{type:"heading",text:"Search"},{type:"list",items:[{inline:[{type:"bold",text:"Ctrl+K shows what your items are worth."},{type:"text",text:" Each of your items in the results carries the value of the copies you hold, next to how many."}],news:!1},{inline:[{type:"bold",text:"Search (Ctrl+K) finds items first, with their picture."},{type:"text",text:' Your items come first, with picture and value, then the catalog and your collections; a command shows when a typed word begins one of its words. Typing "ak" used to put "Switch to light theme" on top, then "StatTrak" and "Snakebite" items, because a command matched as soon as its letters appeared anywhere in it ("d-a-r-k").'}],news:!0},{inline:[{type:"bold",text:"Results are grouped and show what they are."},{type:"text",text:" Items carry their picture, a rarity line and how many you hold. An item you hold once opens its page; one you hold several times opens Holdings filtered to it. A catalog entry opens the Catalog filtered to it."}],news:!1},{inline:[{type:"bold",text:"Every search box finds the same things."},{type:"text",text:' A typed word now has to begin a word of the name, in any order: "ak" finds the AK-47 but no longer every StatTrak™ item, "Snakebite Case" or "Black Lotus". Holdings, History, the Catalog, name suggestions, Prices, Inventories, filter lists and the widget library used to differ; some matched anywhere inside a word, some needed the words in the typed order. Short wears (FN, MW, FT, WW, BS) still work.'}],news:!1},{inline:[{type:"bold",text:"Shift+Enter shows every holding matching the search"},{type:"text",text:', also offered as the last row of "Your items". The keys are listed at the bottom of the box.'}],news:!1}]},{type:"heading",text:"Export"},{type:"list",items:[{inline:[{type:"bold",text:"Export a collection."},{type:"text",text:` A collection's page has "Export CSV" with the same columns as the full holdings export, only its own rows.`}],news:!1},{inline:[{type:"bold",text:"More in the holdings CSV"},{type:"text",text:": rarity, StatTrak and Souvenir, name tag, where a copy came from and where it went, its inventory, its collections, its stickers and charms, its own Sticker Percentage, its notes and its Doppler or Gamma phase. The new columns come after the old ones, so files and tools built on the old layout still read it."}],news:!1},{inline:[{type:"bold",text:"Today's valuation in the holdings CSV"},{type:"text",text:": unit price, value, ask, bid, price source, sticker value, the Sticker Percentage in effect and what it adds, and unrealised and realised P/L, in the ledger currency ("},{type:"code",text:"value_currency"},{type:"text",text:"). The figures are the ones Holdings shows; the sum of "},{type:"code",text:"value_cents"},{type:"text",text:" is the dashboard's portfolio value."}],news:!1},{inline:[{type:"bold",text:"Widgets no longer export CSV."},{type:"text",text:" Exports are for holdings and collections, and every widget figure can be rebuilt from the holdings file."}],news:!1},{inline:[{type:"bold",text:"The price history CSV is gone from Settings."},{type:"text",text:" It wrote every recorded price of every item you ever held, a file few could use and one that grew without bound. Your holdings stay exportable as CSV; in the local app the full backup (SQLite) still contains all prices."}],news:!1}]},{type:"heading",text:"Collections"},{type:"list",items:[{inline:[{type:"bold",text:"Collections are edited in the side panel"},{type:"text",text:", like an item: name, note and colour on the right, the collection's header marked while it is open. It was a dialog in the middle of the screen that hid the page."}],news:!1},{inline:[{type:"bold",text:"An empty Collections page offers a start"},{type:"text",text:': Investment, Trade-up material and For sale, each made with one click, or one of your own. It offered "New collection" twice and nothing to start from.'}],news:!1}]},{type:"heading",text:"Accessibility"},{type:"list",items:[{inline:[{type:"bold",text:"Charts say what they show."},{type:"text",text:' A screen reader announced every dashboard chart as an unnamed "application". Each now carries its message as a label: the latest value and the change since the first point, the three largest parts with their share, or the single figure.'}],news:!1},{inline:[{type:"bold",text:"Every filter has a name for screen readers."},{type:"text",text:' The small heading above a filter was not tied to it, so each one was read out as "Any". Row checkboxes in the Holdings table are now named after their item, and the navigation links no longer carry a second name next to their visible text.'}],news:!1}]},{type:"heading",text:"Charts"},{type:"list",items:[{inline:[{type:"bold",text:"A quieter chart toolbar."},{type:"text",text:' Range, interval and style were three rows of words above every market chart. The range is now one segmented switch, and interval and style sit in a small menu whose button names what is chosen ("Line · Auto").'}],news:!1},{inline:[{type:"bold",text:"Item names on bar charts stay readable."},{type:"text",text:' "Top holdings" cut them in the middle ("DreamHack 2…ir Package"), so neither the start nor the end was left to tell two items apart. The wear is now its short form (FT, MW), StatTrak™ and Souvenir become ST and SV, "Sticker |" is left out, and only what is still too long is cut at the end. The label column is as wide as the longest of them, up to a limit; the full name shows on hover.'}],news:!1},{inline:[{type:"bold",text:"Negative values on a chart axis keep their minus sign."},{type:"text",text:' The value axis of bar and scatter charts had a fixed width, and a long label such as "-100.000 $" was drawn partly outside the chart, so it read as a positive number below zero. The axis is now as wide as its longest label.'}],news:!1},{inline:[{type:"bold",text:"Figure tiles share a baseline."},{type:"text",text:" A tile with a note under its figure and one without sat at different heights; the figure now starts at the top of every tile."}],news:!1},{inline:[{type:"bold",text:"The note under a figure is short."},{type:"text",text:' "Adds up 2650 of 4140 entries; the rest have no figure" took two lines and was cut off on most screens; it now reads "64 % of 4,140 entries", and the full sentence shows on hover.'}],news:!1},{inline:[{type:"bold",text:"Date labels on a narrow chart no longer run into each other."},{type:"text",text:" Labels that would overlap are left out."}],news:!1},{inline:[{type:"bold",text:"The note above an item's price chart shows its number."},{type:"text",text:' It read "{count} of these points are estimates" because the text used a placeholder form the app does not fill in. A test now checks every text for it.'}],news:!1}]},{type:"heading",text:"Phone"},{type:"list",items:[{inline:[{type:"bold",text:"The status bar on a phone shows only what is running."},{type:"text",text:" Version and the legal links moved to the bottom of the menu; in the bar they squeezed the job state into a corner and cut off the version."}],news:!1},{inline:[{type:"bold",text:"Small controls are easier to hit with a finger."},{type:"text",text:" On a touch screen the clear-x in a field, the calendar button and the small icon buttons take a tap from about 40 pixels around them, and checkboxes are a little larger. They were 13 to 16 pixels. With a mouse nothing changes."}],news:!1},{inline:[{type:"bold",text:"Holdings on a phone are one flat list"},{type:"text",text:": picture, name, wear and lock, and value with P/L on the right, about 70 pixels an item. The grid's cards were about 500 pixels each (13,000 pixels of scrolling for 50 items), and the table showed little more than the start of each name. Sorting stays above the list; the table/grid switch and the column picker are left out there."}],news:!1},{inline:[{type:"bold",text:"The portfolio value is back in the top bar on a phone"},{type:"text",text:", and search has a button there. Below tablet width the bar showed neither."}],news:!1},{inline:[{type:"bold",text:"Figure tiles pair up on a phone"},{type:"text",text:" instead of taking a full screen width each, and the figure shrinks to fit the tile rather than being cut off. Notes under a figure stop after two lines."}],news:!1}]}]},{version:"0.13.4",title:"no more waiting behind the dashboard",blocks:[{type:"heading",text:"Speed"},{type:"list",items:[{inline:[{type:"bold",text:"Opening the dashboard no longer holds up every other page."},{type:"text",text:" Drawing the portfolio line wrote a date label for every stored price, about 576,000 times on a large ledger, and each label built a new date formatter. That took over half a minute per chart, and while it ran the server answered nothing else: Holdings opened right after the dashboard could take more than a minute to load. Month names are now formatted once and reused; the same work takes a fraction of a second, and the labels read the same."}],news:!1}]}]}],y="https://github.com/ed3ntim/forcebuy-release/blob/main/CHANGELOG.md";function w(a){return`v${a.replace(/\./g,"-")}`}function l({parts:a}){return e.jsx(e.Fragment,{children:a.map((t,s)=>t.type==="bold"?e.jsx("strong",{className:"font-semibold text-text",children:t.text},s):t.type==="code"?e.jsx("code",{className:"rounded-xs bg-surface-2 px-1 font-mono text-body text-text",children:t.text},s):t.type==="link"?e.jsx(r,{href:t.href,children:t.text},s):e.jsx("span",{children:t.text},s))})}function f({item:a}){return e.jsxs("li",{children:[a.news?e.jsx("span",{className:"mr-2 inline-block rounded-sm border border-accent px-1.5 text-caption font-medium text-accent",children:"New"}):null,e.jsx(l,{parts:a.inline})]})}function u({versions:a}){return e.jsx(e.Fragment,{children:a.map(t=>e.jsxs("section",{className:"space-y-3",children:[e.jsxs("h2",{id:w(t.version),className:"flex items-baseline gap-2 border-b border-line pt-6 pb-1",children:[e.jsx("span",{className:"num text-emphasis font-semibold text-accent",children:t.version}),t.title?e.jsx("span",{className:"text-emphasis font-semibold first-letter:uppercase",children:t.title}):null]}),t.blocks.map((s,n)=>s.type==="heading"?e.jsx("h3",{className:"pt-2 text-ui font-semibold text-text",children:s.text},n):s.type==="paragraph"?e.jsx(i,{children:e.jsx(l,{parts:s.inline})},n):e.jsx("ul",{className:"list-disc space-y-2 pl-5 text-ui leading-relaxed text-text-2",children:s.items.map((h,d)=>e.jsx(f,{item:h},d))},n))]},t.version))})}function v({standalone:a=!1}){return e.jsxs(p,{standalone:a,children:[e.jsx(c,{children:"Changelog"}),e.jsxs(i,{children:["Every ForceBuy release of the last ",o.length,", newest first: new features, changed behaviour and fixed bugs, with the cause of each fix. The full history is in the"," ",e.jsx(r,{href:y,children:"changelog on GitHub"}),"."]}),e.jsx(u,{versions:o})]})}export{y as CHANGELOG_URL,v as ChangelogPage,u as ChangelogVersions,w as versionAnchor};
